ST.xhtml:
TEST('DelayedPass');
IF NOT IS_TEST_FINISHED('DelayedPass') THEN
	_passScan := _passScan + 1;
	AssertTrue(Condition := TRUE, Message := 'delayed-pass');
	IF _passScan = 3 THEN TEST_FINISHED(); END_IF
END_IF

TEST('ChangingFailure');
IF NOT IS_TEST_FINISHED('ChangingFailure') THEN
	_failScan := _failScan + 1;
	_good := _failScan < 3;
	AssertTrue(Condition := _good, Message := 'third-scan-failure');
	IF _failScan = 3 THEN TEST_FINISHED(); END_IF
END_IF

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_QualificationIntegratedA EXTENDS FB_TestSuite
VAR
	_passScan : UINT;
	_failScan : UINT;
	_good : BOOL;
END_VAR

ST.xhtml:
TEST('OtherSuitePass');
IF NOT IS_TEST_FINISHED('OtherSuitePass') THEN
	TEST_FINISHED();
END_IF

InterfaceAsPlainText.xhtml:
PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	FailedCheck : UDINT;
	SnapshotBytes : UDINT;
END_VAR
VAR
	_suite1 : FB_QualificationIntegratedA;
	_suite2 : FB_QualificationIntegratedB;
	_snapshot : REFERENCE TO ST_CoUnitRunSnapshot;

END_VAR
